<style>





/* =====================================================

   ESCONDE NO DESKTOP

===================================================== */



.bluepc-mobile-carousel {



    display: none;



}







/* =====================================================

   MOBILE

===================================================== */



@media (max-width: 767px) {





    /* =================================================

       CARROSSEL

    ================================================= */



    .bluepc-mobile-carousel {



        display: block;



        position: relative;



        width: 100%;



        overflow: hidden;



        padding: 8px 0;



        box-sizing: border-box;



    }





    .bluepc-mobile-carousel * {



        box-sizing: border-box;



    }







    /* =================================================

       TRACK



       PROPORÇÃO:

       1472 x 678

    ================================================= */



    .bluepc-mobile-track {



        position: relative;



        width: 100%;



        aspect-ratio: 1472 / 678;



    }







    /* =================================================

       SLIDES

    ================================================= */



    .bluepc-mobile-slide {



        position: absolute;



        inset: 0;



        width: 100%;



        height: 100%;



        opacity: 0;



        visibility: hidden;



        pointer-events: none;



        transition:

            opacity .45s ease,

            visibility .45s ease;



    }







    .bluepc-mobile-slide.active {



        opacity: 1;



        visibility: visible;



        pointer-events: auto;



        z-index: 2;



    }







    /* =================================================

       BANNER

    ================================================= */



    .bluepc-mobile-banner {



        display: flex;



        align-items: center;



        justify-content: center;



        width: 100%;



        height: 100%;



        overflow: hidden;



        border-radius: 12px;



        background: #050505;



        text-decoration: none;



    }







    /* =================================================

       IMAGEM



       SEM CORTAR

       SEM DISTORCER

    ================================================= */



    .bluepc-mobile-banner img {



        display: block;



        width: 100%;



        height: 100%;



        object-fit: contain;



        object-position: center;



    }







    /* =================================================

       SETAS

    ================================================= */



    .bluepc-mobile-arrow {



        position: absolute;



        top: 50%;



        transform:

            translateY(-50%);



        z-index: 30;



        width: 32px;



        height: 32px;



        padding: 0;



        border: none;



        border-radius: 50%;



        background:

            rgba(255,255,255,.96);



        color: #111111;



        font-family:

            Arial,

            Helvetica,

            sans-serif;



        font-size: 22px;



        line-height: 1;



        display: flex;



        align-items: center;



        justify-content: center;



        cursor: pointer;



        box-shadow:

            0 3px 12px

            rgba(0,0,0,.22);



    }







    .bluepc-mobile-prev {



        left: 5px;



    }







    .bluepc-mobile-next {



        right: 5px;



    }







    /* =================================================

       INDICADORES

    ================================================= */



    .bluepc-mobile-dots {



        position: absolute;



        left: 50%;



        bottom: 10px;



        transform:

            translateX(-50%);



        z-index: 30;



        display: flex;



        align-items: center;



        justify-content: center;



        gap: 5px;



    }







    .bluepc-mobile-dots button {



        width: 7px;



        height: 7px;



        padding: 0;



        border: none;



        border-radius: 20px;



        background:

            rgba(255,255,255,.55);



        cursor: pointer;



        box-shadow:

            0 1px 4px

            rgba(0,0,0,.25);



        transition:

            width .3s ease,

            background .3s ease;



    }







    .bluepc-mobile-dots button.active {



        width: 20px;



        background: #ffffff;



    }





}





</style>&#13;
