<script>



document.addEventListener(

    "DOMContentLoaded",

    function () {





        const carousel =

            document.querySelector(

                ".bluepc-mobile-carousel"

            );





        if (!carousel) {



            return;



        }







        /* =========================================

           ELEMENTOS

        ========================================= */



        const slides =

            carousel.querySelectorAll(

                ".bluepc-mobile-slide"

            );





        const dots =

            carousel.querySelectorAll(

                ".bluepc-mobile-dots button"

            );





        const prev =

            carousel.querySelector(

                ".bluepc-mobile-prev"

            );





        const next =

            carousel.querySelector(

                ".bluepc-mobile-next"

            );







        /* =========================================

           VARIÁVEIS

        ========================================= */



        let current = 0;



        let autoplay;







        /* =========================================

           MOSTRAR SLIDE

        ========================================= */



        function showSlide(index) {





            if (

                index >= slides.length

            ) {



                current = 0;



            }





            else if (

                index < 0

            ) {



                current =

                    slides.length - 1;



            }





            else {



                current = index;



            }







            slides.forEach(

                function (slide) {



                    slide.classList.remove(

                        "active"

                    );



                }

            );





            dots.forEach(

                function (dot) {



                    dot.classList.remove(

                        "active"

                    );



                }

            );







            if (

                slides[current]

            ) {



                slides[current]

                    .classList

                    .add(

                        "active"

                    );



            }







            if (

                dots[current]

            ) {



                dots[current]

                    .classList

                    .add(

                        "active"

                    );



            }



        }







        /* =========================================

           AUTOPLAY

        ========================================= */



        function startAutoplay() {





            clearInterval(

                autoplay

            );





            autoplay =

                setInterval(

                    function () {



                        showSlide(

                            current + 1

                        );



                    },



                    5000



                );



        }







        /* =========================================

           PRÓXIMO

        ========================================= */



        next.addEventListener(

            "click",

            function () {



                showSlide(

                    current + 1

                );



                startAutoplay();



            }

        );







        /* =========================================

           ANTERIOR

        ========================================= */



        prev.addEventListener(

            "click",

            function () {



                showSlide(

                    current - 1

                );



                startAutoplay();



            }

        );







        /* =========================================

           INDICADORES

        ========================================= */



        dots.forEach(

            function (

                dot,

                index

            ) {



                dot.addEventListener(

                    "click",

                    function () {



                        showSlide(

                            index

                        );



                        startAutoplay();



                    }

                );



            }

        );







        /* =========================================

           SWIPE MOBILE

        ========================================= */



        let touchStartX = 0;



        let touchEndX = 0;







        carousel.addEventListener(

            "touchstart",

            function (event) {



                touchStartX =

                    event.changedTouches[0]

                        .screenX;



            },

            {

                passive: true

            }

        );







        carousel.addEventListener(

            "touchend",

            function (event) {



                touchEndX =

                    event.changedTouches[0]

                        .screenX;





                const distance =

                    touchStartX -

                    touchEndX;







                /* ARRASTOU PARA ESQUERDA */



                if (

                    distance > 50

                ) {



                    showSlide(

                        current + 1

                    );



                    startAutoplay();



                }







                /* ARRASTOU PARA DIREITA */



                if (

                    distance < -50

                ) {



                    showSlide(

                        current - 1

                    );



                    startAutoplay();



                }



            },

            {

                passive: true

            }

        );







        /* =========================================

           INICIAR

        ========================================= */



        showSlide(0);



        startAutoplay();





    }

);



</script>

