<script>



document.addEventListener(

    "DOMContentLoaded",

    function () {





        /* =================================================

           ENCONTRAR TODOS OS CARROSSEIS

        ================================================= */



        const carousels =

            document.querySelectorAll(

                ".bluepc-mixed-carousel"

            );







        carousels.forEach(

            function (carousel) {





                /* =========================================

                   ELEMENTOS

                ========================================= */



                const slides =

                    carousel.querySelectorAll(

                        ".bluepc-mixed-slide"

                    );





                const dots =

                    carousel.querySelectorAll(

                        ".bluepc-mixed-dots button"

                    );





                const prev =

                    carousel.querySelector(

                        ".bluepc-mixed-prev"

                    );





                const next =

                    carousel.querySelector(

                        ".bluepc-mixed-next"

                    );







                /* =========================================

                   VARIÁVEIS

                ========================================= */



                let current = 0;



                let autoplay;







                /* =========================================

                   MOSTRAR SLIDE

                ========================================= */



                function showSlide(index) {





                    if (

                        index >=

                        slides.length

                    ) {



                        current = 0;



                    }





                    else if (

                        index < 0

                    ) {



                        current =

                            slides.length - 1;



                    }





                    else {



                        current = index;



                    }







                    /* REMOVER ACTIVE */



                    slides.forEach(

                        function (slide) {



                            slide

                                .classList

                                .remove(

                                    "active"

                                );



                        }

                    );





                    dots.forEach(

                        function (dot) {



                            dot

                                .classList

                                .remove(

                                    "active"

                                );



                        }

                    );







                    /* ATIVAR SLIDE */



                    if (

                        slides[current]

                    ) {



                        slides[current]

                            .classList

                            .add(

                                "active"

                            );



                    }







                    /* ATIVAR DOT */



                    if (

                        dots[current]

                    ) {



                        dots[current]

                            .classList

                            .add(

                                "active"

                            );



                    }



                }







                /* =========================================

                   AUTOPLAY

                ========================================= */



                function startAutoplay() {





                    clearInterval(

                        autoplay

                    );





                    autoplay =

                        setInterval(

                            function () {



                                showSlide(

                                    current + 1

                                );



                            },



                            5000

                        );



                }







                /* =========================================

                   PARAR AUTOPLAY

                ========================================= */



                function stopAutoplay() {



                    clearInterval(

                        autoplay

                    );



                }







                /* =========================================

                   PRÓXIMO

                ========================================= */



                if (next) {



                    next.addEventListener(

                        "click",

                        function () {



                            showSlide(

                                current + 1

                            );



                            startAutoplay();



                        }

                    );



                }







                /* =========================================

                   ANTERIOR

                ========================================= */



                if (prev) {



                    prev.addEventListener(

                        "click",

                        function () {



                            showSlide(

                                current - 1

                            );



                            startAutoplay();



                        }

                    );



                }







                /* =========================================

                   DOTS

                ========================================= */



                dots.forEach(

                    function (

                        dot,

                        index

                    ) {



                        dot.addEventListener(

                            "click",

                            function () {



                                showSlide(

                                    index

                                );



                                startAutoplay();



                            }

                        );



                    }

                );







                /* =========================================

                   PAUSAR NO HOVER

                ========================================= */



                carousel.addEventListener(

                    "mouseenter",

                    stopAutoplay

                );





                carousel.addEventListener(

                    "mouseleave",

                    startAutoplay

                );







                /* =========================================

                   INICIAR

                ========================================= */



                showSlide(0);



                startAutoplay();





            }

        );



    }

);



</script>

