<style>



/* =====================================

   SEÇÃO

===================================== */



.bluepc-gamer-lines {

  width: 100%;



  background: #0b1018;



  padding: 28px 20px 40px;



  box-sizing: border-box;



  font-family: "Inter", Arial, sans-serif;



  color: #f5f7fb;

}





.bluepc-gamer-lines-container {

  width: 100%;



  max-width: 1280px;



  margin: 0 auto;

}





/* =====================================

   CABEÇALHO

===================================== */



.bluepc-gamer-lines-heading {

  margin-bottom: 42px;

}





