  margin: 0 0 18px;



  color: #72d9ff;



  font-size: 12px;



  font-weight: 700;



  line-height: 1.2;



  letter-spacing: 1.8px;



  text-transform: uppercase;

}





.bluepc-gamer-lines-heading h2 {

  margin: 0;



  color: #f5f7fb;



  font-size: 38px;



  line-height: 1.1;



  font-weight: 700;



  letter-spacing: -1.1px;

}





.bluepc-gamer-lines-rule {

  display: block;



  width: 84px;



  height: 2px;



  margin-top: 23px;



  background:

    linear-gradient(

      90deg,

      #24bdff 0%,

      #72d9ff 55%,

      transparent 100%

    );



  box-shadow:

    0 0 12px rgba(36,189,255,.3);

}





/* =====================================

   GRID

===================================== */



.bluepc-gamer-lines-grid {

  display: grid;



  grid-template-columns: repeat(5, minmax(0, 1fr));



  gap: 18px;

}





/* =====================================

   CARD

===================================== */



.bluepc-gamer-line-card {

  min-width: 0;



  display: flex;



  flex-direction: column;



  overflow: hidden;



  background: #131c29;



  border: 1px solid #2d3b4f;



  border-radius: 10px;



  color: inherit !important;



  text-decoration: none !important;



  transition:

    transform .25s ease,

    border-color .25s ease,

    box-shadow .25s ease;

}





.bluepc-gamer-line-card:hover {

  transform: translateY(-5px);



  border-color: #4b9de9;



  box-shadow:

    0 14px 30px rgba(0,0,0,.28);

}





/* =====================================

   IMAGEM

===================================== */



.bluepc-gamer-line-image {

  width: 100%;



  height: 250px;



  overflow: hidden;



  background: #101823;

}





.bluepc-gamer-line-image img {

  width: 100%;



  height: 100%;



  display: block;



  object-fit: cover;



  object-position: center;



  transition:

    transform .35s ease,

    filter .35s ease;

}





.bluepc-gamer-line-card:hover

.bluepc-gamer-line-image img {

  transform: scale(1.025);



  filter: brightness(1.08);

}





/* =====================================

   CONTEÚDO

===================================== */



.bluepc-gamer-line-content {

  flex: 1;



  padding: 24px 19px 22px;



  box-sizing: border-box;



  display: flex;



  flex-direction: column;

}





.bluepc-gamer-line-small {

  display: block;



  margin-bottom: 8px;



  color: #b6c1d0;



  font-size: 10px;



  font-weight: 500;



  line-height: 1.3;



  letter-spacing: .8px;

