.bluepc-gamer-line-content h3 {

  margin: 0 0 24px;



  color: #ffffff;



  font-size: 28px;



  line-height: 1;



  font-weight: 700;



  letter-spacing: -1px;

}





/* =====================================

   LINK

===================================== */



.bluepc-gamer-line-link {

  width: fit-content;



  margin-top: auto;



  padding-bottom: 5px;



  color: #f5f7fb;



  border-bottom: 1px solid #6a8ebc;



  font-size: 13px;



  font-weight: 700;



  line-height: 1.3;



  transition:

    color .2s ease,

    border-color .2s ease;

}





.bluepc-gamer-line-card:hover

.bluepc-gamer-line-link {

  color: #72d9ff;



  border-color: #72d9ff;

}





/* =====================================

   TABLET

===================================== */



@media (max-width: 1024px) {



