    height: auto;



    aspect-ratio: 3 / 4;

  }





  .bluepc-gamer-line-content {

    padding: 18px 14px;

  }





  .bluepc-gamer-line-small {

    font-size: 9px;

  }





  .bluepc-gamer-line-content h3 {

    margin-bottom: 18px;



    font-size: 23px;

  }





  .bluepc-gamer-line-link {

    font-size: 11px;

  }



}





/* =====================================

   CELULAR PEQUENO

