  color: #c0c9d5;



  font-size: 16px;



  line-height: 1.55;



  font-weight: 400;

}





/* LINHA AZUL */



.bluepc-market-line {

  display: block;



  width: 84px;



  height: 2px;



  margin-top: 23px;



  background:

    linear-gradient(

      90deg,

      #24bdff 0%,

      #72d9ff 55%,

      transparent 100%

    );



  box-shadow:

    0 0 12px rgba(36, 189, 255, .3);

}





/* =====================================

   GRID

===================================== */



.bluepc-market-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 16px;

}





/* =====================================

   CARD

===================================== */



.bluepc-market-card {

  min-width: 0;



  min-height: 150px;



  padding: 22px 12px;



  box-sizing: border-box;



  display: flex;



