/* =========================
   SEÇÃO
========================= */

.bluepc-project-section {
  width: 100%;

  background: #090e16;

  padding: 30px 32px 14px;

  box-sizing: border-box;

  font-family: "Inter", Arial, sans-serif;

  color: #ffffff;
}


.bluepc-project-container {
  width: 100%;

  max-width: 1320px;

  margin: 0 auto;
}


/* =========================
   CABEÇALHO
========================= */

.bluepc-project-header {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 80px;

  align-items: start;

  margin-bottom: 76px;
}


.bluepc-project-eyebrow {
  display: block;

  margin-bottom: 25px;

  color: #5fd1ff;

  font-size: 16px;

  font-weight: 700;

  letter-spacing: 2px;

  text-transform: uppercase;
}


.bluepc-project-heading h2 {
  margin: 0;

  color: #f5f5f7;

  font-size: 38px;

  line-height: 1.08;

  font-weight: 700;

  letter-spacing: -1.3px;
}


.bluepc-project-intro {
  max-width: 620px;

  margin-left: auto;
}


.bluepc-project-intro p {
  margin: 0;

  color: #b7c0cc;

  font-size: 16px;

  line-height: 1.65;

  font-weight: 400;
}


/* =========================
   CARDS
========================= */

.bluepc-project-grid {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 22px;
}


.bluepc-project-card {
  min-height: 236px;

  padding: 34px 29px 30px;

  box-sizing: border-box;

  display: flex;

  flex-direction: column;

  justify-content: space-between;

  background: #121c29;

  border: 1px solid #304154;

  border-radius: 10px;

  transition:
    transform .25s ease,
    border-color .25s ease,
    background .25s ease,
    box-shadow .25s ease;
}


.bluepc-project-card:hover {
  transform: translateY(-4px);

  border-color: #4fc8ff;

  background: #152231;

  box-shadow:
    0 15px 35px rgba(0, 0, 0, .25);
}


.bluepc-card-number {
  color: #5bd5ff;

  font-size: 14px;

  font-weight: 500;

  margin-bottom: 34px;
}


.bluepc-card-content h3 {
  margin: 0 0 19px;

  color: #f5f6f8;

  font-size: 20px;

  line-height: 1.25;

  font-weight: 700;

  letter-spacing: -0.4px;
}


.bluepc-card-content p {
  margin: 0;

  max-width: 300px;

  color: #b7c0cc;

  font-size: 14px;

  line-height: 1.65;

  font-weight: 400;
}


/* =========================
   BOTÃO
========================= */

.bluepc-project-cta {
  display: flex;

  justify-content: center;

  margin-top: 37px;
}


.bluepc-project-button {
  display: inline-flex;

  align-items: center;

  justify-content: center;

  min-height: 52px;

  padding: 0 25px;

  box-sizing: border-box;

  border: 1px solid #687b90;

  border-radius: 5px;

  background: transparent;

  color: #ffffff;

  font-size: 14px;

  font-weight: 700;

  text-decoration: none;

  transition:
    background .25s ease,
    border-color .25s ease,
    color .25s ease,
    transform .25s ease;
}


.bluepc-project-button:hover {
  background: #ffffff;

  border-color: #ffffff;

  color: #090e16;

  transform: translateY(-2px);
}


/* =========================
   TABLET
========================= */

@media (max-width: 1024px) {

  .bluepc-project-section {
    padding: 45px 24px;
  }


  .bluepc-project-header {
    grid-template-columns: 1fr;

    gap: 25px;

    margin-bottom: 50px;
  }


  .bluepc-project-intro {
    max-width: 700px;

    margin-left: 0;
  }


  .bluepc-project-grid {
    grid-template-columns: 1fr;
  }


  .bluepc-project-card {
    min-height: 210px;
  }

}


/* =========================
   MOBILE
========================= */

@media (max-width: 767px) {

  .bluepc-project-section {
    padding: 36px 20px;
  }


  .bluepc-project-header {
    margin-bottom: 36px;
  }


  .bluepc-project-eyebrow {
    margin-bottom: 18px;

    font-size: 13px;

    letter-spacing: 1.6px;
  }


  .bluepc-project-heading h2 {
    font-size: 31px;

    line-height: 1.1;
  }


  .bluepc-project-intro p {
    font-size: 15px;

    line-height: 1.6;
  }


  .bluepc-project-grid {
    gap: 16px;
  }


