<style>



/* =====================================

   ÁREA COMPLETA

===================================== */



.bp-marketplace-section {

  width: 100%;

  box-sizing: border-box;



  padding: 64px 0;



  background: #101925;



  border-top: 1px solid #28374a;

  border-bottom: 1px solid #28374a;



  font-family: Arial, Helvetica, sans-serif;



  color: #f5f7fb;

}





/* =====================================

   CONTAINER

===================================== */



.bp-marketplace-container {

  width: min(1280px, calc(100% - 96px));



  margin: 0 auto;

}





/* =====================================

   CABEÇALHO

===================================== */



.bp-marketplace-heading {

  position: relative;



  padding-bottom: 14px;



  margin-bottom: 28px;

}





.bp-marketplace-eyebrow {

  margin: 0 0 14px;



  color: #72d9ff;



  font-size: 12px;



  line-height: 1.4;



  font-weight: 700;



  letter-spacing: 0.12em;



  text-transform: uppercase;

}





.bp-marketplace-heading h2 {

  margin: 0 0 16px;



  color: #f5f7fb;



  font-size: clamp(27px, 2.6vw, 38px);



  line-height: 1.1;



  font-weight: 700;



  letter-spacing: -0.025em;

}





.bp-marketplace-description {

  margin: 0;



  color: #b6c1d0;



  font-size: 16px;



  line-height: 1.65;



  font-weight: 400;

}





/* LINHA AZUL */



.bp-marketplace-heading::after {

  content: "";



  display: block;



  width: 84px;



  height: 2px;



  margin-top: 20px;



  background:

    linear-gradient(

      90deg,

      #24bdff,

      #72d9ff,

      transparent

    );



  box-shadow:

    0 0 12px rgba(36, 189, 255, 0.33);

}





/* =====================================

   GRID

===================================== */



.bp-marketplace-grid {

  display: grid;



  grid-template-columns: repeat(5, minmax(0, 1fr));



  gap: 16px;

}





/* =====================================

   CARDS

===================================== */



.bp-marketplace-card {

  min-width: 0;



  min-height: 150px;



  padding: 22px 12px;



  box-sizing: border-box;



  display: flex;



  flex-direction: column;



  align-items: center;



  justify-content: center;



  background: #151e2b;



  border: 1px solid #343f50;



  border-radius: 10px;



  color: inherit;



  text-align: center;



  text-decoration: none !important;



  overflow: hidden;



  transition:

    transform 0.22s ease,

    border-color 0.22s ease,

    box-shadow 0.22s ease,

    background 0.22s ease;

}





.bp-marketplace-card:hover {

  transform: translateY(-5px);



  border-color: #478cdc;



  background: #172231;



  box-shadow:

    0 12px 24px rgba(0, 0, 0, 0.20);

}





/* =====================================

   LOGOS

===================================== */



.bp-marketplace-logo {

  display: block;



  width: 150px;



  max-width: 100%;



  height: 58px;



  margin: 0 auto 12px;



  overflow: hidden;



  /* transforma todos os logos em branco */

  filter: brightness(0) invert(1);

}





/* =====================================

   LINK

===================================== */



.bp-marketplace-card span {

  display: block;



  margin-top: 12px;



  color: #a9bbd1;



  font-size: 12px;



  line-height: 1.4;



  font-weight: 400;



  transition: color 0.2s ease;

}





.bp-marketplace-card:hover span {

  color: #72d9ff;

}





/* =====================================

   TABLET

===================================== */



@media (max-width: 900px) {



  .bp-marketplace-section {

    padding: 44px 0;

  }



  .bp-marketplace-container {

    width: calc(100% - 40px);

  }



  .bp-marketplace-grid {

    grid-template-columns: repeat(3, minmax(0, 1fr));

  }



}





/* =====================================

   MOBILE

===================================== */



@media (max-width: 640px) {



  .bp-marketplace-container {

    width: calc(100% - 32px);

  }



  .bp-marketplace-heading {

    margin-bottom: 27px;

  }



  .bp-marketplace-heading h2 {

    font-size: 31px;

  }



  .bp-marketplace-description {

    font-size: 15px;



    line-height: 1.55;

  }



  .bp-marketplace-grid {

    grid-template-columns: repeat(2, minmax(0, 1fr));



    gap: 12px;

  }



  .bp-marketplace-card {

    min-height: 125px;



    padding: 18px 12px;

  }



  .bp-marketplace-logo {

    width: 125px;



    height: 50px;

  }



  .bp-marketplace-card span {

    font-size: 11px;

  }



}





/* CELULAR MUITO PEQUENO */



@media (max-width: 380px) {



  .bp-marketplace-grid {

    grid-template-columns: 1fr;

  }



}



</style>

